import java.util.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();
        sc.nextLine();

        String line = sc.nextLine().trim();
        if (n == 0 || line.isEmpty()) {
            sc.close();
            return;
        }

        String[] parts = line.split("\\s+");

        List<String> stringList = Arrays.asList(parts);
        List<Integer> intList = new ArrayList<>();
        boolean isInteger = true;

        for (String part : parts) {
            try {
                intList.add(Integer.parseInt(part));
            } catch (NumberFormatException e) {
                isInteger = false;
                break;
            }
        }

        if (isInteger && intList.size() == n) {
            countFrequency(intList);
        } else {
            countFrequency(stringList);
        }

        sc.close();
    }

    public static <T> void countFrequency(List<T> list) {
        if (list == null || list.size() == 0) {
            return;
        }

        HashMap<T, Integer> frequencyMap = new HashMap<>();

        for (T element : list) {
            frequencyMap.put(element, frequencyMap.getOrDefault(element, 0) + 1);
        }

        List<T> sortedKeys = new ArrayList<>(frequencyMap.keySet());
        Collections.sort(sortedKeys, (a, b) -> {
            String aStr = a.toString();
            String bStr = b.toString();
            int minLen = Math.min(aStr.length(), bStr.length());
            for (int i = 0; i < minLen; i++) {
                char ca = aStr.charAt(i);
                char cb = bStr.charAt(i);
                if (ca != cb) {
                    return Character.compare(ca, cb);
                }
            }
            return Integer.compare(aStr.length(), bStr.length());
        });

        for (T key : sortedKeys) {
            System.out.println(key + " -> " + frequencyMap.get(key));
        }
    }
}
